import {
  BadRequestException,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { Prisma, User } from '@prisma/client';
import { PrismaService } from '../../common/modules/prisma/prisma.service';
import { enqueueMail } from '../mail/mail-outbox';
import { SESSION_TTL_MS } from './auth-token';
// The queued mail that carries a raw token (generated by the caller, stored
// only encrypted in the same transaction as the token's hash).
export interface TokenMail {
  id: string;
  token: string;
}
@Injectable()
export class AuthRepository {
  constructor(private readonly prisma: PrismaService) {}
  findByUsername(username: string) {
    return this.prisma.client.user.findUnique({ where: { username } });
  }
  async createUser(data: Prisma.UserCreateInput, tokenHash: string) {
    return this.prisma.client.$transaction(async (tx) => {
      const user = await tx.user.create({ data });
      await tx.session.create({
        data: {
          userId: user.id,
          tokenHash,
          audience: 'web',
          expiresAt: new Date(Date.now() + SESSION_TTL_MS),
        },
      });
      return user;
    });
  }
  async createSession(
    userId: string,
    tokenHash: string,
    expectedPasswordHash: string,
    expectedEmail?: string
  ) {
    return this.prisma.client.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM woori.users WHERE id=${userId}::uuid FOR UPDATE`;
      const user = await tx.user.findFirst({
        where: {
          id: userId,
          passwordHash: expectedPasswordHash,
          ...(expectedEmail ? { email: expectedEmail } : {}),
          status: 'ACTIVE',
        },
      });
      if (!user)
        throw new UnauthorizedException({
          code: 'INVALID_CREDENTIALS',
          message: '아이디와 비밀번호를 확인해 주세요.',
        });
      return tx.session.create({
        data: {
          userId,
          tokenHash,
          audience: 'web',
          expiresAt: new Date(Date.now() + SESSION_TTL_MS),
        },
      });
    });
  }
  async findSession(tokenHash: string) {
    return this.prisma.client.session.findFirst({
      where: {
        tokenHash,
        audience: 'web',
        revokedAt: null,
        expiresAt: { gt: new Date() },
        user: { status: 'ACTIVE' },
      },
      include: { user: true },
    });
  }
  async revokeSession(tokenHash: string) {
    await this.prisma.client.$transaction(async (tx) => {
      const sessions = await tx.session.findMany({
        where: { tokenHash, audience: 'web' },
        select: { id: true },
      });
      await tx.session.updateMany({
        where: { tokenHash, audience: 'web', revokedAt: null },
        data: { revokedAt: new Date() },
      });
      await tx.pushInstallation.updateMany({
        where: {
          sessionId: { in: sessions.map((s) => s.id) },
          revokedAt: null,
        },
        data: {
          enabled: false,
          revokedAt: new Date(),
          bindingVersion: { increment: 1 },
        },
      });
    });
  }
  async createEmailToken(
    userId: string,
    tokenHash: string,
    expectedEmail: string | undefined,
    mail: TokenMail
  ) {
    return this.prisma.client.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM woori.users WHERE id=${userId}::uuid FOR UPDATE`;
      const user = await tx.user.findFirst({
        where: {
          id: userId,
          status: 'ACTIVE',
          ...(expectedEmail ? { email: expectedEmail } : {}),
        },
      });
      if (!user) return false;
      await tx.emailToken.updateMany({
        where: { userId, purpose: 'VERIFY_EMAIL', consumedAt: null },
        data: { consumedAt: new Date() },
      });
      const created = await tx.emailToken.create({
        data: {
          userId,
          tokenHash,
          purpose: 'VERIFY_EMAIL',
          expiresAt: new Date(Date.now() + 30 * 60 * 1000),
        },
      });
      await enqueueMail(tx, {
        id: mail.id,
        kind: 'VERIFY_EMAIL',
        userId,
        emailTokenId: created.id,
        payload: { to: user.email, token: mail.token },
        expiresAt: created.expiresAt,
      });
      return true;
    });
  }
  async verifyEmail(tokenHash: string, userId: string): Promise<User> {
    return this.prisma.client.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM woori.users WHERE id=${userId}::uuid FOR UPDATE`;
      const now = new Date();
      const token = await tx.emailToken.findUnique({ where: { tokenHash } });
      if (
        !token ||
        token.userId !== userId ||
        token.purpose !== 'VERIFY_EMAIL' ||
        token.consumedAt ||
        token.expiresAt <= now
      )
        throw this.invalidToken();
      const consumed = await tx.emailToken.updateMany({
        where: { id: token.id, consumedAt: null, expiresAt: { gt: now } },
        data: { consumedAt: now },
      });
      if (consumed.count !== 1) throw this.invalidToken();
      const updated = await tx.user.updateMany({
        where: { id: userId, status: 'ACTIVE' },
        data: { verifiedAt: now },
      });
      if (updated.count !== 1) throw this.invalidToken();
      return tx.user.findUniqueOrThrow({ where: { id: userId } });
    });
  }
  private invalidToken() {
    return new BadRequestException({
      code: 'INVALID_VERIFICATION_TOKEN',
      message:
        '인증 링크가 만료되었거나 사용할 수 없어요. 현재 계정에서 새 링크를 요청해 주세요.',
    });
  }
}
